import sympy as s
ROOT=Path(__file__).resolve().parents[3];PACKET=ROOT/'research/voevodsky/global_quartic_discriminant_exposes_the_missing_based_path_data.md';PAIRED=ROOT/'research/nima/results/total-energy-paired-picard-lefschetz.json';RESULT=ROOT/'research/voevodsky/results/global_quartic_discriminant_and_path_gate.json';x,y,E,t,u=s.symbols('x y E t u');z=E-x-y;h=x**2+y**2-z**2;Fu=x**2*u**2-h*u+y**2;Ft=Fu.subs(u,t**2);du=s.factor(s.discriminant(Fu,u));dt=s.factor(s.discriminant(Ft,t));critical=[0,2*x,2*y,2*(x+y)];order=lambda xv,yv,zv:sorted([('0',0),('2x',2*xv),('2y',2*yv),('2xy',2*(xv+yv)),('Ephys',xv+yv+zv)],key=lambda q:q[1]);chambers=[order(1,3,1),order(3,1,1),order(1,3,8)];paired=json.loads(PAIRED.read_text(encoding='utf-8'));text=PACKET.read_text(encoding='utf-8');checks={'quadratic_discriminant':s.simplify(du-(-E*(2*x-E)*(2*y-E)*(2*x+2*y-E)))==0,'quartic_discriminant':s.simplify(dt-16*E**2*x**2*y**2*(2*x-E)**2*(2*y-E)**2*(2*x+2*y-E)**2)==0,'four_critical_values':len(critical)==4,'middle_order_changes':chambers[0].index(('2x',2))<chambers[0].index(('2y',6)) and chambers[1].index(('2y',2))<chambers[1].index(('2x',6)),'physical_base_interval_changes':chambers[0][-1][0]!='Ephys' and chambers[2][-1][0]=='Ephys','source_pair_at_zero':paired['identities']['E0_boundary']=='F(t)|E=0=(x*t^2+y)^2','punctured_base_stated':'mathbb C_E\\setminus\\{0,2x,2y,2(x+y)\\}' in text,'path_authority_gate':'source-authorized basepoint and path homotopy' in text};checks={k:bool(v) for k,v in checks.items()};result={'schema':'marici.voevodsky.global-quartic-discriminant-path-gate.v1','packet_sha256':sha256(PACKET.read_bytes()).hexdigest(),'paired_sha256':sha256(PAIRED.read_bytes()).hexdigest(),'discriminant_u':str(du),'discriminant_t':str(dt),'critical_values':['0','2x','2y','2(x+y)'],'sample_orders':[[label for label,_ in c] for c in chambers],'checks':checks,'passed':all(checks.values()),'disposition':{'global_discriminant':'constructed','based_path_space':'constructed','universal_thimble_marking':'not selected','required':['physical basepoint','fiber branch labels','path homotopy','integral Picard transport']}};RESULT.write_text(json.dumps(result,indent=2)+'\n',encoding='utf-8');print(json.dumps({'passed':result['passed'],'checks':checks,'disposition':result['disposition']}));raise SystemExit(0 if result['passed'] else 1)
